package com.portfolio.features.portfolio.controller; import com.portfolio.common.api.ApiResponse; import com.portfolio.features.portfolio.dto.*; import com.portfolio.features.portfolio.service.PortfolioDesignService; import com.portfolio.features.user.service.UserService; import jakarta.validation.Valid; import java.util.*; import lombok.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/portfolio-sections") @RequiredArgsConstructor public class PortfolioSectionController {private final PortfolioDesignService design;private final UserService users;@GetMapping public ApiResponse<List<SectionResponse>> get(@AuthenticationPrincipal Jwt jwt){return ApiResponse.success("Sections retrieved successfully.",design.get(users.synchronize(jwt)));}@PutMapping public ApiResponse<List<SectionResponse>> update(@AuthenticationPrincipal Jwt jwt,@Valid @RequestBody SectionRequest request){return ApiResponse.success("Sections updated successfully.",design.updateSections(users.synchronize(jwt),request));}}
